arguments.argument:
// Ctrl+Vならボイスパターン切り替え
if( keyboard_check(vk_control) ){
  event_perform(ev_mouse, ev_left_press);
}
// ただのV かつ ボイス再生中でなければボイス再生
else if( current_voice != 0 && !isplaying_sound(prev_voice)){
    if( global.voice_pitch )
      prev_voice = play_sound(global.list_voice[current_voice-1], 0.05);
    else
      prev_voice = play_sound(global.list_voice[current_voice-1], 0);
}
